import{_ as d,a0 as s,w as l,s as p,I as e,x as t,a1 as n,A as i,ao as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const G=JSON.parse('{"title":"安卓编年史（14）：Android 2.3 Gingerbread——第一次 UI 大变 | LCTT x X-CMD","titleTemplate":false,"description":"安卓编年史（14）：Android 2.3 Gingerbread——第一次 UI 大变 | LCTT (The history of Android) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"安卓编年史（14）：Android 2.3 Gingerbread——第一次 UI 大变 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"安卓编年史（14）：Android 2.3 Gingerbread——第一次 UI 大变 | LCTT (The history of Android) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"The history of Android/14 - The history of Android","title":"安卓编年史（14）：Android 2.3 Gingerbread——第一次 UI 大变","tag":"The history of Android","desc":""},"relativePath":"The history of Android/14 - The history of Android.md","filePath":"[post].md"}'),u={name:"The history of Android/14 - The history of Android.md"};function g(m,o,f,x,b,T){const r=s("Link");return l(),p("div",null,[o[31]||(o[31]=e("h1",{id:"安卓编年史-14-android-2-3-gingerbread——第一次-ui-大变",tabindex:"-1"},[t("安卓编年史（14）：Android 2.3 Gingerbread——第一次 UI 大变 "),e("a",{class:"header-anchor",href:"#安卓编年史-14-android-2-3-gingerbread——第一次-ui-大变","aria-label":"Permalink to “安卓编年史（14）：Android 2.3 Gingerbread——第一次 UI 大变”"},"​")],-1)),o[32]||(o[32]=e("h3",{id:"语音操作——口袋里的超级电脑",tabindex:"-1"},[t("语音操作——口袋里的超级电脑 "),e("a",{class:"header-anchor",href:"#语音操作——口袋里的超级电脑","aria-label":"Permalink to “语音操作——口袋里的超级电脑”"},"​")],-1)),e("p",null,[o[1]||(o[1]=t("2010 年 8 月，作为语音搜索应用的一项新功能，“",-1)),n(r,{href:"http://arstechnica.com/gadgets/2010/08/google-beefs-up-voice-search-mobile-sync/"},{default:i(()=>[...o[0]||(o[0]=[t("语音命令",-1)])]),_:1}),o[2]||(o[2]=t("”登陆了安卓市场。语音命令允许用户向他们的手机发出语音命令，然后安卓会试着去理解他们并完成任务。像“导航至[地址]”这样的命令会打开谷歌地图并且开始逐向导航至你所陈述的目的地。你还可以仅仅通过语音来发送短信或电子邮件、拨打电话、打开网站、获取方向，或是在地图上查看一个地点。",-1))]),o[33]||(o[33]=e("p",null,"注：youtube视频地址",-1)),o[34]||(o[34]=e("iframe",{width:"500",height:"281",frameborder:"0",src:"http://www.youtube-nocookie.com/embed/gGbYVvU0Z5s?start=0&wmode=transparent",type:"text/html",style:{display:"block"}},null,-1)),o[35]||(o[35]=e("p",null,"语音命令是谷歌新应用设计哲学的顶峰。语音命令是那时候最先进的语音控制软件，秘密在于谷歌并不在设备上做任运算。一般来说，语音识别是 CPU 密集型任务。实际上，许多语音识别程序仍然有“速度与准确性”设置，用户可以选择他们愿意为语音识别算法运行等待的时间——更多的 CPU 处理意味着更加准确。",-1)),o[36]||(o[36]=e("p",null,"谷歌的创新在于没有劳烦手机上能力有限的处理器来进行语音识别运算。当说出一个命令时，用户的声音会被打包并通过互联网发送到谷歌云服务器。在那里，谷歌超算中心的超级计算机分析并解释语音，然后发送回手机。这是很长的一段旅程，但互联网最终还是有足够快的速度在一两秒内完成像这样的任务。",-1)),o[37]||(o[37]=e("p",null,"很多人抛出词语“云计算”来表达“所有东西都被存储在服务器上”，但这才是真正的云计算。谷歌在云端进行这些巨量的运算操作，又因为在这个问题上投入了看似荒唐的 CPU 资源数目，所以语音识别准确性的唯一限制就是算法本身了。软件不需要由每个用户独立“训练”，因为所有使用语音操作的人无时不刻都在训练它。借助互联网的力量，安卓在你的口袋里放了一部超级电脑，同时相比于已有的解决方案，把语音识别这个工作量从口袋大小的电脑转移到房间大小的电脑上大大提高了准确性。",-1)),e("p",null,[o[4]||(o[4]=t("语音识别作为谷歌的项目已经有一段时间了，它的出现都是因为一个 800 号码。",-1)),n(r,{href:"http://arstechnica.com/business/2007/04/google-rolls-out-free-411-service/"},{default:i(()=>[...o[3]||(o[3]=[t("1-800-GOOG-411",-1)])]),_:1}),o[5]||(o[5]=t("是个谷歌从 2007 年 4 月起开通的免费电话信息服务。它就像 411 信息服务一样工作了多年——用户可以拨打这个号码询问电话号码——但是谷歌免费提供这项服务。查询过程中没有人工的干预，411 服务由语音识别和文本语音转换引擎驱动。在人们教谷歌如何去听之后，又用了三年才有实现语音命令的可能。",-1))]),e("p",null,[o[7]||(o[7]=t("语音识别是谷歌长远思考的极佳范例——公司并不怕在一个可能成不了商业产品的项目上投资多年。今天，语音识别驱动的产品遍布谷歌。它被用在谷歌搜索应用的输入，安卓的语音输入，以及 Google.com。同时它还是 Google Glass 和 ",-1)),n(r,{href:"http://arstechnica.com/gadgets/2014/03/in-depth-with-android-wear-googles-quantum-leap-of-a-smartwatch-os/"},{default:i(()=>[...o[6]||(o[6]=[t("Android Wear",-1)])]),_:1}),o[8]||(o[8]=t(" 的默认输入界面。",-1))]),o[38]||(o[38]=e("p",null,"谷歌甚至还在输入之外的地方使用语音识别。谷歌的语音识别技术被用在了转述 Youtube 视频上，它能自动生成字幕供听障用户观看。生成的字幕甚至被谷歌做成了索引，所以你可以搜索某句话在视频的哪里说过。语音是许多产品的未来，并且这项长期计划将谷歌带入了屈指可数的拥有自家语音识别服务的公司行列。大部分其它的语音识别产品，像苹果的 Siri 和三星设备，只能使用 Nuance 的语音识别，并且为其支付了授权费。",-1)),e("p",null,[o[11]||(o[11]=t("在计算机听觉系统设立运行之后，谷歌下一步将把这项策略应用到计算机视觉上。这就是为什么像 Google Goggles，Google 图像搜索和 ",-1)),n(r,{href:"http://arstechnica.com/gadgets/2014/02/googles-project-tango-is-a-smartphone-with-kinect-style-computer-vision/"},{default:i(()=>[...o[9]||(o[9]=[t("Project Tango",-1)])]),_:1}),o[12]||(o[12]=t(" 这样的项目存在的原因。就像 GOOG-411 的那段日子，这些项目还处在早期阶段。当",-1)),n(r,{href:"http://arstechnica.com/gadgets/2013/12/google-robots-former-android-chief-will-lead-google-robotics-division/"},{default:i(()=>[...o[10]||(o[10]=[t("谷歌的机器人部门",-1)])]),_:1}),o[13]||(o[13]=t("造出了机器人，它会需要看和听，谷歌的计算机视觉和听觉项目会给谷歌一个先机。",-1))]),o[39]||(o[39]=e("p",null,[e("img",{src:"http://cdn.arstechnica.net/wp-content/uploads/2014/03/NS500.png",alt:"Nexus S，第一部三星制造的Nexus手机。"})],-1)),o[40]||(o[40]=e("p",null,[e("em",null,"Nexus S，第一部三星制造的 Nexus 手机。")],-1)),o[41]||(o[41]=e("h3",{id:"android-2-3-gingerbread——第一次-ui-大变",tabindex:"-1"},[t("Android 2.3 Gingerbread——第一次 UI 大变 "),e("a",{class:"header-anchor",href:"#android-2-3-gingerbread——第一次-ui-大变","aria-label":"Permalink to “Android 2.3 Gingerbread——第一次 UI 大变”"},"​")],-1)),o[42]||(o[42]=e("p",null,"Gingerbread（姜饼）发布于 2010 年 12 月，这已是 2.2 发布整整七个月之后了。尽管如此，等待是值得的，因为安卓 2.3 整个系统的每个界面几乎都改变了。这是从安卓 0.9 最初的样式以来第一次重大的更新。2.3 开始了一系列持续的改进，试着将安卓从丑陋的小鸭子变成能承载它自己的合适的样子——从美学角度——来对抗 iPhone。",-1)),o[43]||(o[43]=e("p",null,"说到苹果，六个月前，它发布了 iPhone 4 和 iOS 4，新增了多任务处理和 Facetime 视频聊天。微软同样也终于重返这场竞赛。微软在 2010 年 11 月发布了 Windows Phone 7，也进入了智能手机时代。",-1)),o[44]||(o[44]=e("p",null,"安卓 2.3 在界面设计上投入了很多精力，但是由于缺乏方向或设计文档，许多应用仅仅止步于获得了一个新的定制主题而已。一些应用用了更扁平的暗色主题，一些用了充满渐变、活泼的暗色主题，其他应用则是高对比度的白色和绿色组合。尽管 2.3 并没有做到风格统一，Gingerbread 还是完成了让系统几乎每个部分变得更现代化的任务。这同样是件好事，因为下一个手机版安卓要在将近一年后才到来。",-1)),o[45]||(o[45]=e("p",null,"姜饼的首发设备是 Nexus S，谷歌的第二部旗舰设备，并且是第一部由三星生产的 Nexus 设备。尽管今天我们已经习惯了每年都有更新型号的 CPU，那时候可不是这个样子。Nexus S 有个 1GHz Cortex A8 处理器，和 Nexus One是一样的。GPU 从速度来说略微有所变快。Nexus S 稍微比 Nexus One 大一点，拥有 800×480 分辨率的 AMOLED 显示屏。",-1)),o[46]||(o[46]=e("p",null,"从参数上来说，Nexus S 看起来只是个平淡无奇的升级，但它确实开了安卓的许多先河。Nexus S 是谷歌第一部没有 MicroSD 卡槽的旗舰，板载 16GB 存储。Nexus One 只有 512MB 存储空间，但它有 MicroSD 卡槽。移除 SD 卡槽为用户简化了存储管理——现在只有一个存储地点了——但是影响了高级用户的扩展能力。它是谷歌第一部带有 NFC 的手机，手机背面的一个特殊芯片能够在和其他 NFC 芯片接触时传输数据。Nexus S 暂时只能读取 NFC 标签，而不能发送数据。",-1)),e("p",null,[o[15]||(o[15]=t("托姜饼中一些升级的福，Nexus S 是第一部不带有硬件十字方向键或轨迹球安卓手机之一。Nexus S 缩减到只有电源、音量以及四个导航键。Nexus S 同时还是如今",-1)),n(r,{href:"http://arstechnica.com/gadgets/2013/12/lg-g-flex-review-form-over-even-basic-function/"},{default:i(()=>[...o[14]||(o[14]=[t("疯狂的曲面手机",-1)])]),_:1}),o[16]||(o[16]=t("的先驱，因为三星给 Nexus S 配备了一块略微有些弯曲的玻璃。",-1))]),o[47]||(o[47]=a('<p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/02/appdrawershop.png" alt="姜饼更改了状态栏和壁纸，并且添加了许多新图标。"></p><p><em>姜饼更改了状态栏和壁纸，并且添加了许多新图标。 [Ron Amadeo 供图]</em></p><p>升级过的“Nexus”动态壁纸作为 Nexus S 的独有功能发布。这个壁纸基本上和 Nexus One 的一样，带有带动画轨迹的光点。在 Nexus S 上，去除了方阵设计，取而代之的是波浪形的蓝/灰色背景。底部 dock 有了直角和彩色图标。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/02/32.png" alt="新通知面板和菜单。"></p><p><em>新通知面板和菜单。 [Ron Amadeo 供图]</em></p><p>状态栏自 0.9 的首次登场以来终于得到了重制。状态栏从白色渐变变成纯黑，所有图标重绘成了灰色和绿色。所有东西看起来都更加清爽和现代，这要感谢锐角图标的设计和高分辨率。最奇怪的决定可能是从状态栏时钟移除了时间段显示以及信号强度那令人疑惑的灰色。尽管灰色被用在状态栏的许多图标上，而且上面截图有四格灰色信号，安卓实际上指示的是没有信号。绿色格表示信号强度，灰色格指示的是“空”信号格。</p><p>姜饼的状态栏图标同时还作为网络连接的状态指示。如果你的设备连接到了谷歌的服务器，图标会变绿，如果没有谷歌的连接，图标会是白色的。这让你可以在外出时轻松了解你的网络连接状态。</p><p>通知面板的设计从安卓 1.5 的设计改进而来。我们看到 UI 部分再次从浅色主题变为暗色主题，有个深灰色顶部，黑色背景以及在灰色底色上的黑色文本。</p><p>菜单颜色同样变深了，背景从白色变成了带点透明的黑色。菜单图标和背景的对比并没有它应该有的那么强烈，因为灰色图标的颜色和它们在白色背景上的时候是一样的。要求改变颜色意味着每个开发者都得制作新的图标，所以谷歌在黑色背景上使用了先前就有的灰色。这是系统级别的改变，所以这个新菜单会出现在每个应用中。</p><hr><p><img src="https://cdn.arstechnica.net/wp-content/uploads/2016/05/r.amadeo-45843.jpg" alt="Ron Amadeo"></p>',11)),e("p",null,[n(r,{href:"http://arstechnica.com/author/ronamadeo"},{default:i(()=>[...o[17]||(o[17]=[t("Ron Amadeo",-1)])]),_:1}),o[19]||(o[19]=t(" / Ron是Ars Technica的评论编缉，专注于安卓系统和谷歌产品。他总是在追寻新鲜事物，还喜欢拆解事物看看它们到底是怎么运作的。",-1)),n(r,{href:"https://twitter.com/RonAmadeo"},{default:i(()=>[...o[18]||(o[18]=[t("@RonAmadeo",-1)])]),_:1})]),o[48]||(o[48]=e("hr",null,null,-1)),e("p",null,[o[21]||(o[21]=t("via: ",-1)),n(r,{href:"http://arstechnica.com/gadgets/2016/10/building-android-a-40000-word-history-of-googles-mobile-os/14/"},{default:i(()=>[...o[20]||(o[20]=[t("http://arstechnica.com/gadgets/2016/10/building-android-a-40000-word-history-of-googles-mobile-os/14/",-1)])]),_:1})]),e("p",null,[o[24]||(o[24]=t("译者：",-1)),n(r,{href:"https://github.com/alim0x"},{default:i(()=>[...o[22]||(o[22]=[t("alim0x",-1)])]),_:1}),o[25]||(o[25]=t(" 校对：",-1)),n(r,{href:"https://github.com/wxy"},{default:i(()=>[...o[23]||(o[23]=[t("wxy",-1)])]),_:1})]),e("p",null,[o[28]||(o[28]=t("本文由 ",-1)),n(r,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...o[26]||(o[26]=[t("LCTT",-1)])]),_:1}),o[29]||(o[29]=t(" 原创翻译，",-1)),n(r,{href:"http://linux.cn/"},{default:i(()=>[...o[27]||(o[27]=[t("Linux中国",-1)])]),_:1}),o[30]||(o[30]=t(" 荣誉推出",-1))])])}const S=d(u,[["render",g]]);export{G as __pageData,S as default};
